//! Telemetry event schema for the integration telemetry plugin.
//!
//! Defines the structured event types that are recorded after each routing
//! decision and plugin call. All events are serialized as JSON Lines (JSONL)
//! and appended to `~/.memoryport/telemetry/events.jsonl`.
//!
//! Schema versioning is embedded in every event so consumers can handle
//! forward compatibility gracefully.

use serde::{Deserialize, Serialize};
use std::path::PathBuf;

/// Schema version embedded in every telemetry event.
/// Bump when the event schema changes in a backwards-incompatible way.
pub const SCHEMA_VERSION: &str = "1.0";

/// Well-known route labels used in telemetry events.
pub const ROUTE_LABELS: &[&str] = &["memory_only", "graph_only", "both", "neither"];

/// Quality assessment of a plugin call's result.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ResultQuality {
    /// The result was useful and directly answered the query.
    Useful,
    /// The result was neutral — neither helpful nor harmful.
    Neutral,
    /// The result was not useful or relevant.
    Useless,
}

/// Outcome of the overall routing decision.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum RoutingOutcome {
    /// The route succeeded and produced a useful result.
    Success,
    /// The route partially succeeded (some plugins worked, some failed).
    Partial,
    /// The route failed entirely.
    Failure,
}

/// A record of a single plugin call within a routing decision.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginCall {
    /// Name of the plugin invoked (e.g., "memoryport", "gitnexus", "council").
    pub plugin: String,
    /// How long the call took in milliseconds.
    pub latency_ms: u64,
    /// Whether the call succeeded without error.
    pub success: bool,
    /// Human-readable quality assessment of the result.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub result_quality: Option<ResultQuality>,
}

/// A routing decision event — the primary telemetry record.
///
/// Emitted once per query after all plugin calls have resolved.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RoutingDecisionEvent {
    /// Schema version for forward compatibility.
    pub schema_version: String,
    /// ISO-8601 timestamp of the event.
    pub timestamp: String,
    /// Always `routing_decision` for this event type.
    pub event_type: String,
    /// SHA-256 fingerprint of the query text (hex-encoded, 64 chars).
    pub query_fingerprint: String,
    /// The route that was selected for this query.
    pub chosen_route: String,
    /// Confidence score assigned by the classifier (0.0–1.0).
    pub route_confidence: f64,
    /// Individual plugin call records.
    pub plugin_calls: Vec<PluginCall>,
    /// Total wall-clock time from query receipt to final response (ms).
    pub end_to_end_latency_ms: u64,
    /// Overall outcome of the routing decision.
    pub outcome: RoutingOutcome,

//! Health report aggregation for the integration telemetry plugin.
//!
//! Consumes a collection of [`RoutingDecisionEvent`] records and produces
//! an [`IntegrationHealthReport`] that summarizes the health and performance
//! of each plugin as well as overall routing metrics.

use crate::plugins::telemetry::schema::{RoutingDecisionEvent, RoutingOutcome, SCHEMA_VERSION};
use std::collections::HashMap;

/// Per-plugin health metrics.
#[derive(Debug, Clone)]
pub struct PluginHealth {
    /// Total number of calls to this plugin.
    pub calls: u64,
    /// Number of calls that returned an error.
    pub errors: u64,
    /// Average latency across all successful calls (ms).
    pub avg_latency_ms: f64,
    /// Fraction of calls that succeeded (no error).
    pub success_rate: f64,
}

impl Default for PluginHealth {
    fn default() -> Self {
        Self {
            calls: 0,
            errors: 0,
            avg_latency_ms: 0.0,
            success_rate: 1.0,
        }
    }
}

/// Aggregated health report for all integrations.
#[derive(Debug, Clone)]
pub struct IntegrationHealthReport {
    /// Total number of routing decision events processed.
    pub total_events: u64,
    /// Per-plugin health breakdown.
    pub plugin_health: HashMap<String, PluginHealth>,
    /// Average end-to-end latency across all events (ms).
    pub average_latency_ms: f64,
    /// Fraction of events with outcome != success.
    pub error_rate: f64,
    /// Estimated routing accuracy: fraction of events where outcome == success.
    pub routing_accuracy_estimate: f64,
    /// Fraction of events where council was invoked and converged.
    pub council_convergence_rate: f64,
}

impl Default for IntegrationHealthReport {
    fn default() -> Self {
        Self {
            total_events: 0,
            plugin_health: HashMap::new(),
            average_latency_ms: 0.0,
            error_rate: 0.0,
            routing_accuracy_estimate: 0.0,
            council_convergence_rate: 0.0,
        }
    }
}

/// Aggregate a collection of events into a health report.
pub fn aggregate(events: &[RoutingDecisionEvent]) -> IntegrationHealthReport {
    if events.is_empty() {
        return IntegrationHealthReport::default();
    }

    let total_events = events.len() as u64;
    let mut plugin_health: HashMap<String, PluginHealth> = HashMap::new();

    // Track per-plugin totals for average computation
    let mut plugin_latency_sum: HashMap<String, u64> = HashMap::new();
    let mut total_latency_ms: u64 = 0;
    let mut success_count: u64 = 0;
    let mut partial_count: u64 = 0;
    let mut failure_count: u64 = 0;
    let mut council_converged: u64 = 0;
    let mut council_total: u64 = 0;

